import{_ as t,o as r,c as i,a3 as n}from"./chunks/framework.B5WAEDB7.js";const m=JSON.parse('{"title":"CSV-Import","description":"Daten aus einer CSV-Datei in ein Grid importieren.","frontmatter":{"title":"CSV-Import","description":"Daten aus einer CSV-Datei in ein Grid importieren."},"headers":[],"relativePath":"grids/csv-import.md","filePath":"grids/csv-import.md","lastUpdated":1786086822000}'),a={name:"grids/csv-import.md"};function s(l,e,o,d,h,c){return r(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="csv-import" tabindex="-1">CSV-Import <a class="header-anchor" href="#csv-import" aria-label="Permalink to &quot;CSV-Import&quot;">​</a></h1><p>Über <strong>Aus CSV importieren</strong> übernehmen Sie Daten aus einer Tabellendatei in ein bestehendes Grid.</p><h2 id="voraussetzung-utf-8" tabindex="-1">Voraussetzung: UTF-8 <a class="header-anchor" href="#voraussetzung-utf-8" aria-label="Permalink to &quot;Voraussetzung: UTF-8&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Die Datei muss UTF-8-kodiert sein</p><blockquote><p><em>Die CSV Datei muss im UTF-8 Format erstellt sein.</em></p></blockquote><p>Das ist die häufigste Fehlerquelle. Excel speichert CSV-Dateien je nach Version und Region <strong>nicht</strong> automatisch als UTF-8 — das Ergebnis sind zerstörte Umlaute (<code>Müller</code> wird zu <code>MÃ¼ller</code>).</p><p><strong>So gehen Sie sicher:</strong></p><ul><li><strong>Excel:</strong> <em>Speichern unter</em> → Dateityp <strong>CSV UTF-8 (durch Trennzeichen getrennt)</strong></li><li><strong>LibreOffice Calc:</strong> <em>Speichern unter</em> → CSV → im Dialog <strong>Zeichensatz: Unicode (UTF-8)</strong></li><li><strong>Google Sheets:</strong> Export als CSV ist immer UTF-8</li></ul></div><p>Passt das Format nicht, meldet ApptiveGrid <em>Das Dateiformat ist ungültig.</em></p><h2 id="vorbereitung" tabindex="-1">Vorbereitung <a class="header-anchor" href="#vorbereitung" aria-label="Permalink to &quot;Vorbereitung&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Vor dem Import prüfen</p><ol><li><strong>Zielspalten anlegen.</strong> Der Import schreibt in bestehende Felder. Legen Sie fehlende Spalten mit dem <a href="/referenz/spaltentypen">passenden Typ</a> vorher an.</li><li><strong>Flows prüfen.</strong> Hängt ein Flow mit dem Auslöser <em>Neuer Eintrag</em> an diesem Grid, startet er <strong>für jede importierte Zeile</strong>. Bei 500 Zeilen gehen 500 E-Mails raus. Schalten Sie den Flow vorher ab oder importieren Sie in ein Zwischengrid.</li><li><strong>Eintragsgrenze beachten.</strong> Die Anzahl der Einträge je Grid ist tarifabhängig.</li><li><strong>Sicherung ziehen.</strong> Bei einem Import in ein gefülltes Grid vorher einen <a href="/grids/csv-export">CSV-Export</a> machen.</li></ol></div><h2 id="ablauf" tabindex="-1">Ablauf <a class="header-anchor" href="#ablauf" aria-label="Permalink to &quot;Ablauf&quot;">​</a></h2><p>Der Import führt durch vier Schritte.</p><h3 id="_1-·-csv-datei-einlesen" tabindex="-1">1 · CSV Datei einlesen <a class="header-anchor" href="#_1-·-csv-datei-einlesen" aria-label="Permalink to &quot;1 · CSV Datei einlesen&quot;">​</a></h3><ul><li>Über <strong>Datei Laden</strong> wählen Sie die Datei.</li><li><strong>Kopfzeile?</strong> gibt an, ob die erste Zeile Spaltennamen enthält.</li><li><strong>CSV einlesen</strong> startet die Auswertung.</li></ul><p>Danach ordnen Sie die Spalten einander zu. Die Tabelle hat zwei Spalten:</p><table tabindex="0"><thead><tr><th>Überschrift</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>Grid</strong></td><td>Die Zielspalte in ApptiveGrid</td></tr><tr><td><strong>CSV</strong></td><td>Die Quellspalte aus der Datei</td></tr></tbody></table><p>Spalten, die Sie nicht übernehmen wollen, setzen Sie auf <strong>Ignorieren</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Kopfzeile spart Zuordnungsarbeit</p><p>Mit Kopfzeile zeigt die Zuordnung sprechende Namen statt „Spalte 1&quot;, „Spalte 2&quot;. Bei mehr als fünf Spalten ist das ein spürbarer Unterschied — und eine Fehlerquelle weniger.</p></div><h3 id="_2-·-vorschau" tabindex="-1">2 · Vorschau <a class="header-anchor" href="#_2-·-vorschau" aria-label="Permalink to &quot;2 · Vorschau&quot;">​</a></h3><p>Zeigt, wie die Daten ankommen würden.</p><div class="tip custom-block"><p class="custom-block-title">Hier wirklich hinsehen</p><p>Die Vorschau ist die letzte Gelegenheit vor dem Schreiben. Prüfen Sie besonders:</p><ul><li><strong>Umlaute</strong> — kaputt heißt: falsche Kodierung, Import abbrechen</li><li><strong>Datumsangaben</strong> — kommen sie als Datum an oder als Text?</li><li><strong>Zahlen</strong> — Dezimaltrennzeichen richtig interpretiert?</li><li><strong>Auswahlfelder</strong> — passen die Werte zu den vorhandenen Optionen?</li></ul></div><p>Mit <strong>Daten importieren</strong> starten Sie.</p><h3 id="_3-·-importieren" tabindex="-1">3 · Importieren <a class="header-anchor" href="#_3-·-importieren" aria-label="Permalink to &quot;3 · Importieren&quot;">​</a></h3><p>Der Fortschritt wird angezeigt: <em>Es werden {Anzahl} Einträge importiert.</em></p><h3 id="_4-·-abgeschlossen" tabindex="-1">4 · Abgeschlossen <a class="header-anchor" href="#_4-·-abgeschlossen" aria-label="Permalink to &quot;4 · Abgeschlossen&quot;">​</a></h3><p>Abschlussmeldung: <em>Es wurden {Anzahl} Einträge erfolgreich importiert.</em></p><div class="tip custom-block"><p class="custom-block-title">Zahl gegenprüfen</p><p>Vergleichen Sie die gemeldete Zahl mit der Zeilenzahl Ihrer Datei. Weichen sie ab, wurden Zeilen übersprungen — meist wegen unpassender Werte.</p></div><h2 id="typische-probleme" tabindex="-1">Typische Probleme <a class="header-anchor" href="#typische-probleme" aria-label="Permalink to &quot;Typische Probleme&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Ursache und Lösung</th></tr></thead><tbody><tr><td><code>MÃ¼ller</code> statt <code>Müller</code></td><td>Datei ist nicht UTF-8. Neu speichern, Import wiederholen.</td></tr><tr><td><em>Das Dateiformat ist ungültig.</em></td><td>Keine gültige CSV. Prüfen Sie Trennzeichen und Kodierung.</td></tr><tr><td><em>Unerkanntes Datumsformat : {date}</em></td><td>Datumsformat nicht lesbar. <code>JJJJ-MM-TT</code> ist am zuverlässigsten.</td></tr><tr><td>Zahlen kommen als Text an</td><td>Zielspalte ist vom Typ <em>Text</em>. Typ vorher ändern.</td></tr><tr><td>Auswahlfelder bleiben leer</td><td>Die CSV-Werte entsprechen keiner Option. Optionen vorher anlegen oder <em>Andere Optionen zulassen</em> aktivieren.</td></tr><tr><td>Weniger Einträge als Zeilen</td><td>Zeilen mit unpassenden Werten wurden übersprungen.</td></tr><tr><td>Plötzlich viele Flow-Läufe</td><td>Ein Flow mit <em>Neuer Eintrag</em> hängt am Grid.</td></tr></tbody></table><h2 id="ein-testlauf-lohnt-sich" tabindex="-1">Ein Testlauf lohnt sich <a class="header-anchor" href="#ein-testlauf-lohnt-sich" aria-label="Permalink to &quot;Ein Testlauf lohnt sich&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Erst zehn Zeilen</p><p>Bei größeren Datenmengen: Kopieren Sie die ersten zehn Zeilen in eine eigene Datei und importieren Sie zuerst diese. Stimmt das Ergebnis, importieren Sie den Rest — andernfalls haben Sie zehn statt tausend Zeilen aufzuräumen.</p><p>Zum Aufräumen eines missglückten Imports hilft die <a href="/grids/eintraege-loeschen">Mehrfachlöschung</a>; die zuletzt importierten Einträge finden Sie über eine Sortierung nach <em>Erstellt am</em>.</p></div><h2 id="was-der-import-nicht-kann" tabindex="-1">Was der Import nicht kann <a class="header-anchor" href="#was-der-import-nicht-kann" aria-label="Permalink to &quot;Was der Import nicht kann&quot;">​</a></h2><ul><li><strong>Bestehende Einträge aktualisieren.</strong> Der Import legt immer neue Einträge an. Es gibt keinen Abgleich über eine Schlüsselspalte.</li><li><strong>Verknüpfungen herstellen.</strong> Verweise auf andere Grids lassen sich nicht direkt importieren.</li><li><strong>Dateien übernehmen.</strong> Anhänge müssen separat hochgeladen werden.</li></ul><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/grids/csv-export">CSV-Export</a></li><li><a href="/referenz/spaltentypen">Spaltentypen-Referenz</a></li><li><a href="/fehlerbehebung/haeufige-fehlermeldungen">Häufige Fehlermeldungen</a></li></ul>',32)])])}const u=t(a,[["render",s]]);export{m as __pageData,u as default};
